    "V": [
      "Acquired bradykinin-mediated angioedema (e.g., acquired C1-esterase inhibitor deficiency): Can cause rapid lip/tongue swelling and airway compromise due to increased vascular permeability; however, lacks a clear food trigger typically."
    ],
    "I": [
      "Lip cellulitis/cheilitis: Infectious swelling of the lip; would usually have pain, warmth, erythema and a more gradual onset, making it less consistent with this rapid post-ingestion course.",
      "Contact mucositis (irritant/inflammatory): Local inflammatory reaction to a food/spice; could cause localized swelling but typically without systemic symptoms."
    ],
    "N": [],
    "D": [],
    "I2": [
      "ACE inhibitor–induced angioedema: Can present with isolated lip/tongue swelling and airway symptoms; no ACE inhibitor use reported here.",
      "Scombroid (histamine) fish poisoning: Rapid flushing, oral burning, palpitations after certain fish; prawn is not typical, and others are usually affected."
    ],
    "C": [
      "Hereditary angioedema (C1-esterase inhibitor deficiency): Recurrent angioedema without urticaria; can involve airway. Usually not food-triggered and often has family history."
    ],
    "A": [
      "IgE-mediated shellfish (prawn) allergy with anaphylaxis: Classic rapid-onset angioedema and respiratory symptoms within 30–60 minutes of ingestion; history of atopy increases risk.",
      "IgE-mediated food allergy with acute angioedema/urticaria (without full anaphylaxis): Localized swelling after food exposure; can occur without rash.",
      "Contact urticaria/oral allergy syndrome to food/spices: Local lip swelling after contact; systemic symptoms are less typical."
    ],
